-- Let me check the solar panel status and wind turbine status columns
SELECT DISTINCT solarpanelstatus, windturbinestatus 
FROM thermalsolarwindandgrid;

-- All outputs are non-zero. Let me also check for null solar or wind data:
SELECT COUNT(*) FROM thermalsolarwindandgrid 
WHERE renewablemetrics->'solar' IS NULL OR renewablemetrics->'wind' IS NULL;

-- Both tables have 1000 records. Let me check if there are any equipment codes in location that don't match thermalsolarwindandgrid
SELECT COUNT(*) FROM location l 
WHERE NOT EXISTS (SELECT 1 FROM thermalsolarwindandgrid t WHERE l.loceqref = t.thermaleqref);

